sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    /* =====================================================
       INITIAL STATE
    ===================================================== */

    c.answers = {
        answer1: '',
        answer2: '',
        answer3: ''
    };

    c.submitting = false;
    c.submitted = false;
    c.refreshing = false;

    c.withdrawing = false;
    c.showWithdrawModal = false;
    c.withdrawReason = '';

    c.errorMessage = '';


    /* =====================================================
       SUBMIT CLAIM
    ===================================================== */

    c.submitClaim = function() {

        c.errorMessage = '';


        if (
            !c.answers.answer1 ||
            !c.answers.answer1.trim()
        ) {

            c.errorMessage =
                'Please answer question 1.';

            return;
        }


        if (
            !c.answers.answer2 ||
            !c.answers.answer2.trim()
        ) {

            c.errorMessage =
                'Please answer question 2.';

            return;
        }


        c.submitting = true;


        c.server.get({

            action:
                'submitClaim',

            match_id:
                c.data.match.sys_id,

            answer1:
                c.answers.answer1,

            answer2:
                c.answers.answer2,

            answer3:
                c.answers.answer3

        }).then(

            function(response) {

                c.submitting = false;


                if (
                    !response.data.success
                ) {

                    c.errorMessage =
                        response.data.message ||
                        response.data.error ||
                        'Verification could not be submitted.';


                    if (
                        response.data.claim
                    ) {

                        c.data.claim =
                            response.data.claim;

                        c.data.canVerify =
                            false;
                    }


                    return;
                }


                c.data.claim =
                    response.data.claim;


                c.data.canVerify =
                    false;


                c.submitted =
                    true;


                $window.scrollTo(
                    0,
                    0
                );
            },


            function() {

                c.submitting =
                    false;

                c.errorMessage =
                    'Verification could not be submitted. Please try again.';
            }
        );
    };


    /* =====================================================
       REFRESH STATUS
    ===================================================== */

    c.refreshStatus = function() {

        c.errorMessage = '';

        c.refreshing = true;


        c.server.get({

            action:
                'refreshStatus',

            match_id:
                c.data.match.sys_id

        }).then(

            function(response) {

                c.refreshing = false;


                if (
                    response.data.error
                ) {

                    c.errorMessage =
                        response.data.error;

                    return;
                }


                if (
                    response.data.claim
                ) {

                    c.data.claim =
                        response.data.claim;

                    c.data.canVerify =
                        false;
                }
            },


            function() {

                c.refreshing =
                    false;

                c.errorMessage =
                    'Unable to refresh verification status.';
            }
        );
    };


    /* =====================================================
       OPEN WITHDRAW MODAL
    ===================================================== */

    c.openWithdrawModal = function() {

        c.errorMessage = '';

        c.withdrawReason = '';

        c.showWithdrawModal = true;
    };


    /* =====================================================
       CLOSE WITHDRAW MODAL
    ===================================================== */

    c.closeWithdrawModal = function() {

        if (
            c.withdrawing
        ) {

            return;
        }


        c.showWithdrawModal = false;

        c.withdrawReason = '';
    };


    /* =====================================================
       WITHDRAW CLAIM
    ===================================================== */

    c.withdrawClaim = function() {

        if (
            c.withdrawing
        ) {

            return;
        }


        c.errorMessage = '';

        c.withdrawing = true;


        c.server.get({

            action:
                'withdrawClaim',

            match_id:
                c.data.match.sys_id,

            withdrawal_reason:
                c.withdrawReason || ''

        }).then(

            function(response) {

                c.withdrawing = false;


                if (
                    !response.data.success
                ) {

                    c.errorMessage =
                        response.data.message ||
                        response.data.error ||
                        'The claim could not be withdrawn.';


                    if (
                        response.data.claim
                    ) {

                        c.data.claim =
                            response.data.claim;
                    }


                    return;
                }


                c.data.claim =
                    response.data.claim;


                c.data.canVerify =
                    false;


                c.showWithdrawModal =
                    false;


                c.withdrawReason =
                    '';


                $window.scrollTo(
                    0,
                    0
                );
            },


            function() {

                c.withdrawing =
                    false;

                c.errorMessage =
                    'The claim could not be withdrawn. Please try again.';
            }
        );
    };


    /* =====================================================
       RESULT CSS CLASS
    ===================================================== */

    c.resultClass = function() {

        var status =
            (
                c.data.claim &&
                c.data.claim.statusValue
                    ?
                    c.data.claim.statusValue
                    :
                    ''
            )
            .toString()
            .toLowerCase();


        if (
            status ===
            'withdrawn'
        ) {

            return 'withdrawn';
        }


        var result =
            (
                c.data.claim &&
                c.data.claim.verificationResult
                    ?
                    c.data.claim.verificationResult
                    :
                    ''
            )
            .toString()
            .toLowerCase();


        if (
            result ===
            'pass'
        ) {

            return 'pass';
        }


        if (
            result ===
            'review'
        ) {

            return 'review';
        }


        if (
            result ===
            'fail'
        ) {

            return 'fail';
        }


        return '';
    };

};

sp_widget.css:
/* ==========================================================
   CAMPUSMATCH OWNERSHIP VERIFICATION
   WEBSITE + NOW MOBILE APP
   FULL-BLEED SAFE VERSION
========================================================== */

.cm-verify-page {
  position: relative;
  display: block;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  margin-top: 0 !important;
  margin-bottom: 0 !important;

  min-height: 100vh;
  min-height: 100svh;

  padding:
    42px
    20px
    90px;

  background:
    linear-gradient(
      180deg,
      #FBF8EF 0%,
      #F5F7F0 100%
    ) !important;

  box-shadow:
    0 -60px 0 #FBF8EF,
    0 60px 0 #F5F7F0;

  color: #102E34;

  font-family:
    "DM Sans",
    "Segoe UI",
    sans-serif;

  box-sizing: border-box !important;
  overflow-x: hidden;
}


.cm-verify-page,
.cm-verify-page *,
.cm-verify-page *::before,
.cm-verify-page *::after {
  box-sizing: border-box;
}


.cm-verify-container {
  width: 100%;
  max-width: 720px;

  margin: 0 auto;
}


/* ==========================================================
   BACK
========================================================== */

.cm-back-link {
  display: inline-flex;

  margin-bottom: 26px;

  color: #15564B !important;

  font-size: 13px;
  font-weight: 700;

  text-decoration: none !important;
}


/* ==========================================================
   HEADER
========================================================== */

.cm-verify-header {
  max-width: 620px;

  margin:
    0
    auto
    30px;

  text-align: center;
}


.cm-eyebrow {
  display: inline-flex;

  padding:
    8px
    16px;

  margin-bottom: 15px;

  border-radius: 999px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 12px;
  font-weight: 800;
}


.cm-verify-header h1 {
  margin:
    0
    0
    10px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 38px;
  font-weight: 700;

  letter-spacing: -1px;
}


.cm-verify-header p {
  margin: 0;

  color: #617477;

  font-size: 14px;
  line-height: 1.65;
}


/* ==========================================================
   ITEM SUMMARY
========================================================== */

.cm-item-summary {
  display: flex;
  align-items: center;

  gap: 15px;

  padding: 19px 21px;

  margin-bottom: 17px;

  border:
    1px solid #D2DED8;

  border-radius: 20px;

  background: #FFFFFF;

  box-shadow:
    0 5px 17px rgba(16,78,69,.05);
}


.cm-item-icon {
  width: 56px;
  height: 56px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 17px;

  background: #EDF5E9;

  color: #15564B;
}


.cm-item-icon svg {
  width: 28px;
  height: 28px;
}


.cm-item-summary-main {
  min-width: 0;
}


.cm-item-summary-main > span {
  display: block;

  margin-bottom: 3px;

  color: #7A898D;

  font-size: 10px;
  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .45px;
}


.cm-item-summary-main h2 {
  margin:
    0
    0
    7px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 18px;
}


.cm-item-meta {
  display: flex;
  flex-wrap: wrap;

  gap:
    6px
    12px;

  color: #718185;

  font-size: 10px;
}


/* ==========================================================
   PRIVACY NOTE
========================================================== */

.cm-privacy-note {
  display: flex;
  align-items: flex-start;

  gap: 11px;

  padding: 15px 17px;

  margin-bottom: 20px;

  border-radius: 16px;

  background: #EDF5E9;
}


.cm-privacy-note > svg {
  width: 20px;
  height: 20px;

  flex-shrink: 0;

  color: #15564B;
}


.cm-privacy-note strong {
  display: block;

  margin-bottom: 2px;

  color: #104E45;

  font-size: 12px;
}


.cm-privacy-note p {
  margin: 0;

  color: #687A7E;

  font-size: 11px;
  line-height: 1.55;
}


/* ==========================================================
   QUESTION CARD
========================================================== */

.cm-question-card {
  padding: 30px;

  border:
    1px solid #D2DED8;

  border-radius: 24px;

  background: #FFFFFF;

  box-shadow:
    0 8px 26px rgba(16,78,69,.07);
}


.cm-question-heading {
  display: flex;
  align-items: flex-start;

  gap: 12px;

  margin-bottom: 13px;
}


.cm-question-number {
  width: 36px;
  height: 36px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 12px;

  background: #EDF5E9;

  color: #15564B;

  font-size: 12px;
  font-weight: 800;
}


.cm-question-heading h3 {
  margin:
    0
    0
    3px;

  color: #104E45;

  font-size: 15px;
}


.cm-question-heading p {
  margin: 0;

  color: #77878A;

  font-size: 10px;
  line-height: 1.45;
}


.cm-question-card textarea {
  width: 100%;

  min-height: 92px;

  padding: 13px 15px;

  border:
    1.5px solid #D2DED8;

  border-radius: 14px;

  outline: 0;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;
  font-size: 13px;

  resize: vertical;

  transition:
    border .2s ease,
    box-shadow .2s ease;
}


.cm-question-card textarea:focus {
  border-color: #249D78;

  box-shadow:
    0 0 0 4px rgba(36,157,120,.10);
}


.cm-question-divider {
  height: 1px;

  margin:
    27px
    0;

  background: #EDF2EE;
}


/* ==========================================================
   FORM ERROR
========================================================== */

.cm-form-error {
  padding:
    12px
    14px;

  margin-top: 20px;

  border-radius: 12px;

  background: #FBEAE7;

  color: #A44732;

  font-size: 11px;
  font-weight: 700;
}


/* ==========================================================
   SUBMIT
========================================================== */

.cm-submit-button {
  width: 100%;

  min-height: 52px;

  margin-top: 24px;

  border: 0;

  border-radius: 999px;

  background: #104E45;

  color: #FFFFFF;

  font-family: inherit;

  font-size: 13px;
  font-weight: 800;

  cursor: pointer;

  box-shadow:
    0 8px 20px rgba(16,78,69,.16);

  transition:
    transform .2s ease,
    background .2s ease;
}


.cm-submit-button:hover {
  transform: translateY(-1px);

  background: #15564B;
}


.cm-submit-button:disabled {
  opacity: .55;

  cursor: not-allowed;

  transform: none;
}


.cm-submit-note {
  max-width: 500px;

  margin:
    12px
    auto
    0;

  color: #849194;

  font-size: 9px;
  line-height: 1.5;

  text-align: center;
}


/* ==========================================================
   STATUS CARD
========================================================== */

.cm-status-card {
  padding: 35px;

  border:
    1px solid #D2DED8;

  border-radius: 24px;

  background: #FFFFFF;

  text-align: center;

  box-shadow:
    0 8px 27px rgba(16,78,69,.07);
}


.cm-result-icon {
  width: 70px;
  height: 70px;

  margin:
    0
    auto
    16px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #EDF2EE;

  color: #617477;

  font-size: 24px;
  font-weight: 800;
}


.cm-result-icon svg {
  width: 31px;
  height: 31px;
}


.cm-result-icon.pass {
  background: #E4F4EA;

  color: #168C70;
}


.cm-result-icon.review {
  background: #FDF3DC;

  color: #8B681B;
}


.cm-result-icon.fail {
  background: #FBEAE7;

  color: #B5502F;
}


.cm-status-eyebrow {
  display: block;

  margin-bottom: 7px;

  color: #168C70;

  font-size: 10px;
  font-weight: 800;

  text-transform: uppercase;

  letter-spacing: .6px;
}


.cm-status-card h2 {
  margin:
    0
    0
    8px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 24px;
}


.cm-status-card > div > p {
  max-width: 520px;

  margin:
    0
    auto;

  color: #687A7E;

  font-size: 12px;
  line-height: 1.6;
}


/* ==========================================================
   CURRENT STATUS
========================================================== */

.cm-current-status {
  max-width: 390px;

  margin:
    23px
    auto;

  padding:
    13px
    16px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 15px;

  border-radius: 14px;

  background: #F4F8F2;
}


.cm-current-status span {
  color: #77878A;

  font-size: 10px;
}


.cm-current-status strong {
  color: #104E45;

  font-size: 11px;
}


/* ==========================================================
   TIMELINE
========================================================== */

.cm-timeline {
  max-width: 470px;

  margin:
    29px
    auto
    0;

  padding-left: 5px;

  text-align: left;
}


.cm-timeline-item {
  position: relative;

  min-height: 65px;

  display: flex;
  align-items: flex-start;

  gap: 13px;
}


.cm-timeline-item:not(:last-child)::after {
  content: "";

  position: absolute;

  top: 18px;
  left: 7px;

  width: 2px;
  height: 49px;

  background: #DCE5DF;
}


.cm-timeline-dot {
  position: relative;

  z-index: 2;

  width: 16px;
  height: 16px;

  margin-top: 2px;

  flex-shrink: 0;

  border:
    3px solid #FFFFFF;

  border-radius: 50%;

  background: #CBD7D1;

  box-shadow:
    0 0 0 2px #CBD7D1;
}


.cm-timeline-item.completed .cm-timeline-dot {
  background: #249D78;

  box-shadow:
    0 0 0 2px #249D78;
}


.cm-timeline-item.active .cm-timeline-dot {
  background: #E7B74A;

  box-shadow:
    0 0 0 2px #E7B74A;
}


.cm-timeline-item strong {
  display: block;

  color: #102E34;

  font-size: 11px;
}


.cm-timeline-item small {
  display: block;

  margin-top: 2px;

  color: #849194;

  font-size: 9px;
}


/* ==========================================================
   STATUS ACTIONS
========================================================== */

.cm-status-actions {
  margin-top: 15px;

  display: flex;
  align-items: center;
  justify-content: center;

  gap: 10px;
}


.cm-status-actions button,
.cm-status-actions a {
  padding:
    10px
    16px;

  border-radius: 999px;

  font-family: inherit;

  font-size: 10px;
  font-weight: 800;

  cursor: pointer;

  text-decoration: none !important;
}


.cm-status-actions button {
  border: 0;

  background: #104E45;

  color: #FFFFFF;
}


.cm-status-actions a {
  border:
    1.5px solid #D2DED8;

  background: #FFFFFF;

  color: #104E45 !important;
}


/* ==========================================================
   WITHDRAWN STATE
========================================================== */

.cm-result-icon.withdrawn {
  background: #FBEAE7;

  color: #B5502F;
}


.cm-withdrawal-meta {
  max-width: 520px;

  margin:
    16px
    auto
    0;

  padding:
    12px
    14px;

  display: flex;
  flex-direction: column;

  gap: 4px;

  border-radius: 13px;

  background: #FFF7F4;

  color: #8D4B39;

  font-size: 10px;
  line-height: 1.5;
}


.cm-status-actions .cm-withdraw-button {
  border:
    1.5px solid #E5B9AD;

  background: #FFFFFF;

  color: #A44732;
}


.cm-status-actions .cm-withdraw-button:hover {
  background: #FFF5F2;
}


/* ==========================================================
   WITHDRAW CONFIRMATION MODAL
========================================================== */

.cm-modal-backdrop {
  position: fixed;

  z-index: 10000;

  inset: 0;

  padding: 20px;

  display: flex;
  align-items: center;
  justify-content: center;

  background:
    rgba(
      16,
      46,
      52,
      .42
    );

  backdrop-filter:
    blur(3px);
}


.cm-withdraw-modal {
  width: 100%;
  max-width: 470px;

  padding:
    30px;

  border:
    1px solid #D2DED8;

  border-radius: 24px;

  background: #FFFFFF;

  box-shadow:
    0 24px 70px rgba(16,46,52,.22);

  text-align: center;
}


.cm-withdraw-modal-icon {
  width: 58px;
  height: 58px;

  margin:
    0
    auto
    15px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #FDF3DC;

  color: #8B681B;

  font-size: 23px;
  font-weight: 900;
}


.cm-withdraw-modal h2 {
  margin:
    0
    0
    8px;

  color: #104E45;

  font-family:
    "Plus Jakarta Sans",
    "Segoe UI",
    sans-serif;

  font-size: 22px;
}


.cm-withdraw-modal > p {
  margin:
    0
    auto
    20px;

  color: #687A7E;

  font-size: 12px;
  line-height: 1.6;
}


.cm-withdraw-modal label {
  display: block;

  margin-bottom: 7px;

  color: #102E34;

  font-size: 11px;
  font-weight: 800;

  text-align: left;
}


.cm-withdraw-modal textarea {
  width: 100%;

  min-height: 95px;

  padding:
    12px
    14px;

  border:
    1.5px solid #D2DED8;

  border-radius: 14px;

  outline: 0;

  background: #FFFFFF;

  color: #102E34;

  font-family: inherit;
  font-size: 12px;

  resize: vertical;
}


.cm-withdraw-modal textarea:focus {
  border-color: #249D78;

  box-shadow:
    0 0 0 4px rgba(36,157,120,.10);
}


.cm-modal-error {
  margin-top: 12px;

  padding:
    10px
    12px;

  border-radius: 12px;

  background: #FBEAE7;

  color: #A44732;

  font-size: 10px;
  font-weight: 700;

  text-align: left;
}


.cm-withdraw-modal-actions {
  margin-top: 20px;

  display: flex;
  justify-content: flex-end;

  gap: 10px;
}


.cm-withdraw-modal-actions button {
  min-width: 125px;

  padding:
    11px
    17px;

  border-radius: 999px;

  font-family: inherit;

  font-size: 11px;
  font-weight: 800;

  cursor: pointer;
}


.cm-withdraw-modal-actions button:disabled {
  opacity: .55;

  cursor: not-allowed;
}


.cm-modal-cancel {
  border:
    1.5px solid #D2DED8;

  background: #FFFFFF;

  color: #104E45;
}


.cm-modal-confirm {
  border: 0;

  background: #A44732;

  color: #FFFFFF;
}


/* ==========================================================
   ERROR STATE
========================================================== */

.cm-state-card {
  max-width: 500px;

  margin: 50px auto;

  padding: 50px 28px;

  border:
    1px solid #D2DED8;

  border-radius: 23px;

  background: #FFFFFF;

  text-align: center;
}


.cm-state-icon {
  width: 62px;
  height: 62px;

  margin:
    0
    auto
    15px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #EDF5E9;

  color: #15564B;

  font-size: 24px;
  font-weight: 800;
}


.cm-state-card h2 {
  color: #104E45;
}


.cm-state-card p {
  color: #718185;
}


.cm-state-card a {
  color: #168C70 !important;

  font-weight: 700;

  text-decoration: none !important;
}


/* ==========================================================
   TABLET
========================================================== */

@media (max-width: 760px) {

  .cm-verify-page {
    min-height: 100svh;

    padding:
      36px
      16px
      75px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }

}


/* ==========================================================
   MOBILE
========================================================== */

@media (max-width: 560px) {

  .cm-verify-page {
    min-height: 100svh;

    padding:
      30px
      14px
      65px;

    box-shadow:
      0 -60px 0 #FBF8EF,
      0 60px 0 #F5F7F0;
  }


  .cm-verify-header h1 {
    font-size: 30px;
  }


  .cm-item-summary {
    align-items: flex-start;

    padding:
      16px;
  }


  .cm-item-icon {
    width: 48px;
    height: 48px;
  }


  .cm-item-meta {
    flex-direction: column;

    gap: 3px;
  }


  .cm-question-card {
    padding:
      23px
      18px;
  }


  .cm-status-card {
    padding:
      29px
      18px;
  }


  .cm-status-actions {
    flex-direction: column;
  }


  .cm-status-actions button,
  .cm-status-actions a {
    width: 100%;

    text-align: center;
  }


  .cm-withdraw-modal {
    padding:
      25px
      18px;
  }


  .cm-withdraw-modal-actions {
    flex-direction: column-reverse;
  }


  .cm-withdraw-modal-actions button {
    width: 100%;
  }

}


/* ==========================================================
   EXTRA SMALL MOBILE
========================================================== */

@media (max-width: 390px) {

  .cm-verify-page {
    padding:
      27px
      10px
      58px;
  }


  .cm-verify-header h1 {
    font-size: 27px;
  }


  .cm-item-summary {
    gap: 11px;
    padding: 14px;
  }


  .cm-item-icon {
    width: 44px;
    height: 44px;

    border-radius: 14px;
  }


  .cm-question-card {
    padding:
      20px
      15px;
  }


  .cm-status-card {
    padding:
      26px
      15px;
  }


  .cm-withdraw-modal {
    padding:
      22px
      15px;
  }

}

sp_widget.script:
(function() {

    /* ======================================================
       TABLES
    ====================================================== */

    var ITEM_TABLE =
        'x_snc_campusmatch_campusmatch_item';

    var MATCH_TABLE =
        'x_snc_campusmatch_campusmatch_match';

    var CLAIM_TABLE =
        'x_snc_campusmatch_campusmatch_claim';


    /* ======================================================
       DEFAULT DATA
    ====================================================== */

    data.error = '';

    data.success = false;

    data.message = '';

    data.match = null;

    data.canVerify = false;

    data.claim = {
        exists: false
    };


    /* ======================================================
       HELPER - FIND FIRST VALID FIELD
    ====================================================== */

    function findField(
        gr,
        names
    ) {

        for (
            var i = 0;
            i < names.length;
            i++
        ) {

            if (
                gr.isValidField(
                    names[i]
                )
            ) {

                return names[i];
            }
        }


        return '';
    }


    /* ======================================================
       MATCH ID
    ====================================================== */

    var matchId = '';


    if (
        input &&
        input.match_id
    ) {

        matchId =
            input.match_id
                .toString()
                .trim();
    }
    else {

        matchId =
            (
                $sp.getParameter(
                    'match_id'
                ) || ''
            )
            .toString()
            .trim();
    }


    if (!matchId) {

        data.error =
            'No Match was provided.';

        return;
    }


    /* ======================================================
       LOAD MATCH
    ====================================================== */

    var match =
        new GlideRecord(
            MATCH_TABLE
        );


    if (
        !match.get(
            matchId
        )
    ) {

        data.error =
            'Match record could not be found.';

        return;
    }


    /* ======================================================
       MATCH STATUS
    ====================================================== */

    var matchStatus =
        (
            match.getValue(
                'status'
            ) || ''
        )
        .toString()
        .toLowerCase()
        .trim();


    /* ======================================================
       MATCH SCORE
    ====================================================== */

    var overall =
        parseFloat(
            match.getValue(
                'overall_score'
            )
        );


    if (
        isNaN(overall)
    ) {

        overall = 0;
    }


    overall =
        Math.round(
            overall * 100
        ) / 100;


    /* ======================================================
       MATCH LEVEL
    ====================================================== */

    var matchLevel =
        (
            match.getValue(
                'match_level'
            ) || ''
        )
        .toString()
        .toLowerCase()
        .trim();


    if (!matchLevel) {

        if (
            overall >= 80
        ) {

            matchLevel =
                'strong';
        }
        else if (
            overall >= 65
        ) {

            matchLevel =
                'potential';
        }
        else {

            matchLevel =
                'low';
        }
    }


    /* ======================================================
       INVALID / LOW MATCH
    ====================================================== */

    if (
        matchStatus ===
        'no_match'
    ) {

        data.error =
            'This Match is no longer available for ownership verification.';

        return;
    }


    if (
        overall < 65 ||
        matchLevel ===
        'low'
    ) {

        data.error =
            'This Match does not meet the minimum score required for ownership verification.';

        return;
    }


    /* ======================================================
       POTENTIAL MATCH SECURITY

       Potential Match normally requires staff review first.

       Rejected / Withdrawn are allowed to LOAD here only
       because an existing Claim may need to show its final
       status page. A NEW Claim is still blocked later.
    ====================================================== */

    if (
        matchLevel ===
        'potential'
    ) {

        var hasReviewAudit =
            false;


        if (
            match.isValidField(
                'reviewed_by'
            ) &&
            match.getValue(
                'reviewed_by'
            )
        ) {

            hasReviewAudit =
                true;
        }


        if (
            match.isValidField(
                'reviewed_on'
            ) &&
            match.getValue(
                'reviewed_on'
            )
        ) {

            hasReviewAudit =
                true;
        }


        var potentialAllowed =
            (
                matchStatus ===
                'confirmed'
            ) ||
            (
                matchStatus ===
                'active' &&
                hasReviewAudit
            ) ||
            (
                matchStatus ===
                'withdrawn'
            ) ||
            (
                matchStatus ===
                'rejected'
            );


        if (!potentialAllowed) {

            data.error =
                'Campus staff must verify this Potential Match before ownership verification can begin.';

            return;
        }
    }


    /* ======================================================
       ITEM REFERENCES
    ====================================================== */

    var lostId =
        match.getValue(
            'lost_item'
        );


    var foundId =
        match.getValue(
            'found_item'
        );


    if (
        !lostId ||
        !foundId
    ) {

        data.error =
            'The Match does not contain valid Lost and Found Items.';

        return;
    }


    /* ======================================================
       LOAD LOST / FOUND ITEMS
    ====================================================== */

    var lost =
        new GlideRecord(
            ITEM_TABLE
        );


    var found =
        new GlideRecord(
            ITEM_TABLE
        );


    if (
        !lost.get(
            lostId
        ) ||
        !found.get(
            foundId
        )
    ) {

        data.error =
            'Matched Item records could not be loaded.';

        return;
    }


    /* ======================================================
       ONLY LOST REPORT OWNER MAY ACCESS VERIFICATION
    ====================================================== */

    var access =
        new CampusMatchAccess();


    if (
        !access.ownsItem(
            lost
        )
    ) {

        data.error =
            'Only the Lost report owner can complete ownership verification.';

        return;
    }


    var userId =
        access.getUserId();


    /* ======================================================
       SAFE MATCH DATA

       PRIVATE FOUND DETAILS ARE NEVER SENT TO CLIENT.
    ====================================================== */

    data.match = {

        sys_id:
            match.getUniqueValue(),

        overallScore:
            overall,

        publicTitle:
            found.getDisplayValue(
                'public_title'
            ) ||
            'Found Item',

        category:
            found.getDisplayValue(
                'category'
            ) ||
            '—',

        location:
            found.getDisplayValue(
                'location_zone'
            ) ||
            'Campus'
    };


    /* ======================================================
       SAFE VERIFICATION QUESTIONS
    ====================================================== */

    data.questions = {

        question1:
            (
                found.getValue(
                    'verification_question_1'
                ) || ''
            )
            .toString(),

        question2:
            (
                found.getValue(
                    'verification_question_2'
                ) || ''
            )
            .toString(),

        question3:
            (
                found.getValue(
                    'verification_question_3'
                ) || ''
            )
            .toString()
    };


    /* ======================================================
       CLAIM TABLE
    ====================================================== */

    var claimTemplate =
        new GlideRecord(
            CLAIM_TABLE
        );


    if (
        !claimTemplate.isValid()
    ) {

        data.error =
            'CampusMatch Claim table could not be found.';

        return;
    }


    /* ======================================================
       CLAIM FIELD DETECTION
    ====================================================== */

    var CLAIM_MATCH =
        findField(
            claimTemplate,
            [
                'u_match',
                'match'
            ]
        );


    var CLAIM_ITEM =
        findField(
            claimTemplate,
            [
                'u_item',
                'item'
            ]
        );


    var CLAIM_CLAIMANT =
        findField(
            claimTemplate,
            [
                'u_claimant',
                'claimant'
            ]
        );


    var CLAIM_STATUS =
        findField(
            claimTemplate,
            [
                'u_claim_status',
                'claim_status',
                'status'
            ]
        );


    var CLAIM_DATE =
        findField(
            claimTemplate,
            [
                'u_claim_date',
                'claim_date'
            ]
        );


    var CLAIM_ANSWER_1 =
        findField(
            claimTemplate,
            [
                'u_claimant_answer_1',
                'claimant_answer_1'
            ]
        );


    var CLAIM_ANSWER_2 =
        findField(
            claimTemplate,
            [
                'u_claimant_answer_2',
                'claimant_answer_2'
            ]
        );


    var CLAIM_ANSWER_3 =
        findField(
            claimTemplate,
            [
                'u_claimant_answer_3',
                'claimant_answer_3'
            ]
        );


    var CLAIM_SCORE =
        findField(
            claimTemplate,
            [
                'u_verification_score',
                'verification_score'
            ]
        );


    var CLAIM_RESULT =
        findField(
            claimTemplate,
            [
                'u_verification_result',
                'verification_result'
            ]
        );


    var CLAIM_NUMBER =
        findField(
            claimTemplate,
            [
                'number',
                'u_number'
            ]
        );


    var CLAIM_HANDOVER_COMPLETED =
        findField(
            claimTemplate,
            [
                'u_handover_completed',
                'handover_completed'
            ]
        );


    var CLAIM_WITHDRAWAL_REASON =
        findField(
            claimTemplate,
            [
                'u_withdrawal_reason',
                'withdrawal_reason'
            ]
        );


    var CLAIM_WITHDRAWN_BY =
        findField(
            claimTemplate,
            [
                'u_withdrawn_by',
                'withdrawn_by'
            ]
        );


    var CLAIM_WITHDRAWN_ON =
        findField(
            claimTemplate,
            [
                'u_withdrawn_on',
                'withdrawn_on'
            ]
        );


    /* ======================================================
       REQUIRED CLAIM FIELDS
    ====================================================== */

    if (!CLAIM_MATCH) {

        data.error =
            'Match field could not be found on the Claim table.';

        return;
    }


    if (!CLAIM_ITEM) {

        data.error =
            'Item field could not be found on the Claim table.';

        return;
    }


    if (!CLAIM_CLAIMANT) {

        data.error =
            'Claimant field could not be found on the Claim table.';

        return;
    }


    if (!CLAIM_STATUS) {

        data.error =
            'Claim Status field could not be found on the Claim table.';

        return;
    }


    if (!CLAIM_DATE) {

        data.error =
            'Claim Date field could not be found on the Claim table.';

        return;
    }


    if (!CLAIM_ANSWER_1) {

        data.error =
            'Claimant Answer 1 field could not be found.';

        return;
    }


    if (!CLAIM_ANSWER_2) {

        data.error =
            'Claimant Answer 2 field could not be found.';

        return;
    }


    if (!CLAIM_ANSWER_3) {

        data.error =
            'Claimant Answer 3 field could not be found.';

        return;
    }


    if (!CLAIM_RESULT) {

        data.error =
            'Verification Result field could not be found.';

        return;
    }


    /* ======================================================
       BUILD SAFE CLAIM RESPONSE
    ====================================================== */

    function buildClaim(
        claim
    ) {

        if (!claim) {

            return {
                exists: false,
                canWithdraw: false
            };
        }


        var statusValue =
            (
                claim.getValue(
                    CLAIM_STATUS
                ) || ''
            )
            .toString()
            .toLowerCase()
            .trim();


        var resultValue =
            (
                claim.getValue(
                    CLAIM_RESULT
                ) ||
                'pending'
            )
            .toString()
            .toLowerCase()
            .trim();


        var scoreValue =
            '0';


        if (
            CLAIM_SCORE
        ) {

            scoreValue =
                claim.getValue(
                    CLAIM_SCORE
                ) || '0';
        }


        var claimNumber =
            '';


        if (
            CLAIM_NUMBER
        ) {

            claimNumber =
                claim.getDisplayValue(
                    CLAIM_NUMBER
                ) || '';
        }


        if (!claimNumber) {

            claimNumber =
                claim
                    .getUniqueValue()
                    .substring(
                        0,
                        8
                    );
        }


        var handoverCompleted =
            false;


        if (
            CLAIM_HANDOVER_COMPLETED
        ) {

            handoverCompleted =
                claim.getValue(
                    CLAIM_HANDOVER_COMPLETED
                ) == '1';
        }


        /*
         * Claim can be withdrawn until physical handover.
         *
         * Rejected and already-withdrawn claims cannot
         * be withdrawn.
         */
        var canWithdraw =
            (
                !handoverCompleted &&
                statusValue !==
                'rejected' &&
                statusValue !==
                'withdrawn'
            );


        var withdrawalReason =
            '';


        if (
            CLAIM_WITHDRAWAL_REASON
        ) {

            withdrawalReason =
                (
                    claim.getValue(
                        CLAIM_WITHDRAWAL_REASON
                    ) || ''
                )
                .toString();
        }


        var withdrawnBy =
            '';


        if (
            CLAIM_WITHDRAWN_BY &&
            claim.getValue(
                CLAIM_WITHDRAWN_BY
            )
        ) {

            withdrawnBy =
                claim.getDisplayValue(
                    CLAIM_WITHDRAWN_BY
                ) || '';
        }


        var withdrawnOn =
            '';


        if (
            CLAIM_WITHDRAWN_ON &&
            claim.getValue(
                CLAIM_WITHDRAWN_ON
            )
        ) {

            withdrawnOn =
                claim.getDisplayValue(
                    CLAIM_WITHDRAWN_ON
                ) || '';
        }


        return {

            exists:
                true,

            sys_id:
                claim.getUniqueValue(),

            number:
                claimNumber,

            statusValue:
                statusValue,

            statusDisplay:
                claim.getDisplayValue(
                    CLAIM_STATUS
                ) ||
                'Submitted',

            verificationScore:
                scoreValue,

            verificationResult:
                resultValue,

            verificationDisplay:
                claim.getDisplayValue(
                    CLAIM_RESULT
                ) ||
                'Pending',

            handoverCompleted:
                handoverCompleted,

            canWithdraw:
                canWithdraw,

            isWithdrawn:
                statusValue ===
                'withdrawn',

            withdrawalReason:
                withdrawalReason,

            withdrawnBy:
                withdrawnBy,

            withdrawnOn:
                withdrawnOn
        };
    }


    /* ======================================================
       FIND CURRENT USER'S CLAIM FOR THIS MATCH

       VERY IMPORTANT:
       This means another user's Claim cannot be modified.
    ====================================================== */

    function findClaim() {

        var gr =
            new GlideRecord(
                CLAIM_TABLE
            );


        gr.addQuery(
            CLAIM_MATCH,
            matchId
        );


        gr.addQuery(
            CLAIM_CLAIMANT,
            userId
        );


        gr.orderByDesc(
            'sys_created_on'
        );


        gr.setLimit(
            1
        );


        gr.query();


        if (
            gr.next()
        ) {

            return gr;
        }


        return null;
    }


    /* ======================================================
       REFRESH CLAIM STATUS
    ====================================================== */

    if (
        input &&
        input.action ===
        'refreshStatus'
    ) {

        data.claim =
            buildClaim(
                findClaim()
            );


        data.success =
            true;

        return;
    }


    /* ======================================================
       WITHDRAW CLAIM
    ====================================================== */

    if (
        input &&
        input.action ===
        'withdrawClaim'
    ) {

        var claimToWithdraw =
            findClaim();


        /* --------------------------------------------------
           CLAIM MUST EXIST
        -------------------------------------------------- */

        if (
            !claimToWithdraw
        ) {

            data.success =
                false;

            data.message =
                'No ownership claim was found for this Match.';

            return;
        }


        var currentClaimStatus =
            (
                claimToWithdraw.getValue(
                    CLAIM_STATUS
                ) || ''
            )
            .toString()
            .toLowerCase()
            .trim();


        /* --------------------------------------------------
           HANDOVER CHECK
        -------------------------------------------------- */

        var handoverAlreadyCompleted =
            false;


        if (
            CLAIM_HANDOVER_COMPLETED
        ) {

            handoverAlreadyCompleted =
                claimToWithdraw.getValue(
                    CLAIM_HANDOVER_COMPLETED
                ) == '1';
        }


        if (
            handoverAlreadyCompleted
        ) {

            data.success =
                false;

            data.message =
                'This claim cannot be withdrawn because the item has already been collected.';

            data.claim =
                buildClaim(
                    claimToWithdraw
                );

            return;
        }


        /* --------------------------------------------------
           ALREADY WITHDRAWN
        -------------------------------------------------- */

        if (
            currentClaimStatus ===
            'withdrawn'
        ) {

            data.success =
                false;

            data.message =
                'This claim has already been withdrawn.';

            data.claim =
                buildClaim(
                    claimToWithdraw
                );

            return;
        }


        /* --------------------------------------------------
           REJECTED CLAIM
        -------------------------------------------------- */

        if (
            currentClaimStatus ===
            'rejected'
        ) {

            data.success =
                false;

            data.message =
                'A rejected claim cannot be withdrawn.';

            data.claim =
                buildClaim(
                    claimToWithdraw
                );

            return;
        }


        /* --------------------------------------------------
           WITHDRAWAL FIELDS REQUIRED
        -------------------------------------------------- */

        if (
            !CLAIM_WITHDRAWAL_REASON ||
            !CLAIM_WITHDRAWN_BY ||
            !CLAIM_WITHDRAWN_ON
        ) {

            data.success =
                false;

            data.message =
                'Withdrawal audit fields are not configured on the Claim table.';

            return;
        }


        /* --------------------------------------------------
           WITHDRAWAL REASON
        -------------------------------------------------- */

        var withdrawalReason =
            (
                input.withdrawal_reason ||
                ''
            )
            .toString()
            .trim();


        if (
            withdrawalReason.length >
            500
        ) {

            withdrawalReason =
                withdrawalReason.substring(
                    0,
                    500
                );
        }


        /* --------------------------------------------------
           UPDATE CLAIM
        -------------------------------------------------- */

        claimToWithdraw.setValue(
            CLAIM_STATUS,
            'withdrawn'
        );


        claimToWithdraw.setValue(
            CLAIM_WITHDRAWAL_REASON,
            withdrawalReason
        );


        claimToWithdraw.setValue(
            CLAIM_WITHDRAWN_BY,
            userId
        );


        claimToWithdraw.setValue(
            CLAIM_WITHDRAWN_ON,
            new GlideDateTime()
        );


        var withdrawnClaimId =
            claimToWithdraw.update();


        if (
            !withdrawnClaimId
        ) {

            data.success =
                false;

            data.message =
                'The claim could not be withdrawn.';

            return;
        }


        claimToWithdraw.get(
            withdrawnClaimId
        );


        /* ==================================================
           UPDATE MATCH

           DO NOT touch AI scores.
           DO NOT touch Match Level.
           Only lifecycle Status changes.
        ================================================== */

        if (
            match.isValidField(
                'status'
            )
        ) {

            match.setValue(
                'status',
                'withdrawn'
            );


            match.update();
        }


        /* ==================================================
           IMPORTANT

           Collection Token is intentionally NOT deleted.

           The QR Collection widget must reject the token
           because Claim Status is no longer Approved.

           Handover Completed remains FALSE.

           Lost / Found records are NOT resolved here.
        ================================================== */


        data.success =
            true;


        data.message =
            'Your ownership claim has been withdrawn.';


        data.claim =
            buildClaim(
                claimToWithdraw
            );


        data.canVerify =
            false;

        return;
    }


    /* ======================================================
       SUBMIT OWNERSHIP CLAIM
    ====================================================== */

    if (
        input &&
        input.action ===
        'submitClaim'
    ) {

        /* --------------------------------------------------
           CLOSED MATCH CANNOT BE CLAIMED AGAIN
        -------------------------------------------------- */

        if (
            matchStatus ===
            'withdrawn' ||
            matchStatus ===
            'rejected'
        ) {

            data.success =
                false;


            data.message =
                'This Match is no longer available for a new ownership claim.';


            data.claim =
                buildClaim(
                    findClaim()
                );


            data.canVerify =
                false;

            return;
        }


        /* --------------------------------------------------
           ANSWERS
        -------------------------------------------------- */

        var answer1 =
            (
                input.answer1 || ''
            )
            .toString()
            .trim();


        var answer2 =
            (
                input.answer2 || ''
            )
            .toString()
            .trim();


        var answer3 =
            (
                input.answer3 || ''
            )
            .toString()
            .trim();


        /* --------------------------------------------------
           FIRST TWO QUESTIONS REQUIRED
        -------------------------------------------------- */

        if (
            !answer1 ||
            !answer2
        ) {

            data.success =
                false;

            data.message =
                'Please answer the first two ownership questions.';

            return;
        }


        /* --------------------------------------------------
           EXISTING CLAIM CHECK
        -------------------------------------------------- */

        var claim =
            findClaim();


        /*
         * IMPORTANT:
         *
         * ONE USER + ONE MATCH = ONE CLAIM ONLY.
         *
         * This prevents:
         *
         * Rejected → claim again
         * Withdrawn → claim again
         * Approved → claim again
         * Submitted → duplicate claim
         */
        if (
            claim
        ) {

            data.success =
                false;


            data.message =
                'You already have an ownership claim for this Match.';


            data.claim =
                buildClaim(
                    claim
                );


            data.canVerify =
                false;

            return;
        }


        /* ==================================================
           CREATE NEW CLAIM
        ================================================== */

        claim =
            new GlideRecord(
                CLAIM_TABLE
            );


        claim.initialize();


        claim.setValue(
            CLAIM_MATCH,
            matchId
        );


        claim.setValue(
            CLAIM_ITEM,
            foundId
        );


        claim.setValue(
            CLAIM_CLAIMANT,
            userId
        );


        claim.setValue(
            CLAIM_STATUS,
            'Submitted'
        );


        claim.setValue(
            CLAIM_DATE,
            new GlideDateTime()
        );


        /*
         * Insert first.
         *
         * Then save answers so your existing verification
         * Business Rule can process the updated Claim.
         */

        var insertedId =
            claim.insert();


        if (
            !insertedId
        ) {

            data.success =
                false;

            data.message =
                'Claim could not be created.';

            return;
        }


        claim.get(
            insertedId
        );


        /* ==================================================
           SAVE ANSWERS
        ================================================== */

        claim.setValue(
            CLAIM_ANSWER_1,
            answer1
        );


        claim.setValue(
            CLAIM_ANSWER_2,
            answer2
        );


        claim.setValue(
            CLAIM_ANSWER_3,
            answer3
        );


        var updatedId =
            claim.update();


        if (
            !updatedId
        ) {

            data.success =
                false;

            data.message =
                'Verification answers could not be saved.';

            return;
        }


        claim.get(
            updatedId
        );


        /* ==================================================
           RESPONSE
        ================================================== */

        data.success =
            true;


        data.message =
            'Ownership verification submitted.';


        data.claim =
            buildClaim(
                claim
            );


        data.canVerify =
            false;

        return;
    }


    /* ======================================================
       NORMAL PAGE LOAD
    ====================================================== */

    var existingClaim =
        findClaim();


    data.claim =
        buildClaim(
            existingClaim
        );


    /*
     * Only show the verification form when NO Claim
     * exists for this current user + Match.
     *
     * Rejected / Withdrawn users cannot reclaim.
     */
    data.canVerify =
        (
            !data.claim.exists &&
            matchStatus !==
            'withdrawn' &&
            matchStatus !==
            'rejected'
        );

})();
